const $=s=>document.querySelector(s),canvas=$('#scene'),ctx=canvas.getContext('2d');
let count=innerWidth<600?1000:2400,shape='orbit',particles=[],targets=[],width=0,height=0,angle=0,paused=matchMedia('(prefers-reduced-motion: reduce)').matches,pointerX=0,pointerY=0,stream=null,tracker=null,tracking=false,starting=false,epoch=0,lastVideo=-1,candidate='',since=0,lastFrame=0;
const names={orbit:'Orbital',heart:'Heart',cloud:'Stardust',logo:'NV. Monogram',love:'I LOVE YOU'},colors={orbit:[77,180,255],heart:[255,99,165],cloud:[125,165,255],logo:[77,224,255],love:[255,135,185]};
const textCanvas=document.createElement('canvas');textCanvas.width=500;textCanvas.height=220;const tc=textCanvas.getContext('2d');tc.fillStyle='white';tc.font='900 170px Arial';tc.textAlign='center';tc.fillText('NV.',250,170);const pixels=tc.getImageData(0,0,500,220).data,logo=[];for(let y=0;y<220;y+=3)for(let x=0;x<500;x+=3)if(pixels[(y*500+x)*4+3]>100)logo.push([(x-250)/140,(110-y)/140,0]);
const loveCanvas=document.createElement('canvas');loveCanvas.width=680;loveCanvas.height=230;const lc=loveCanvas.getContext('2d');lc.fillStyle='white';lc.font='800 83px Arial';lc.textAlign='center';lc.fillText('I LOVE YOU',340,145);const lovePixels=lc.getImageData(0,0,680,230).data,love=[];for(let y=0;y<230;y+=2)for(let x=0;x<680;x+=2)if(lovePixels[(y*680+x)*4+3]>100)love.push([(x-340)/150,(115-y)/150,0]);
function target(i){const t=i/count*Math.PI*2;if(shape==='love'){if(i<count*.82){const p=love[Math.floor(i/(count*.82)*love.length)];return[p[0],p[1],(Math.random()-.5)*.06]}const a=Math.random()*Math.PI*2,r=.12+Math.random()*.05,side=i%2===0?-1:1;return[side*1.05+16*Math.sin(a)**3/11*r,.92+(13*Math.cos(a)-5*Math.cos(2*a)-2*Math.cos(3*a)-Math.cos(4*a))/11*r,(Math.random()-.5)*.08]}if(shape==='logo'){const p=logo[i%logo.length];return[p[0],p[1],(Math.random()-.5)*.15]}if(shape==='heart'){const a=Math.random()*Math.PI*2,r=.75+Math.random()*.25;return[16*Math.sin(a)**3/11*r,(13*Math.cos(a)-5*Math.cos(2*a)-2*Math.cos(3*a)-Math.cos(4*a))/11*r,(Math.random()-.5)*.4]}if(shape==='orbit'&&i>count*.42){const r=1.5+Math.random()*.55;return[Math.cos(t)*r,Math.sin(t)*r*.22,Math.sin(t)*r*.8]}const u=Math.random()*2-1,a=Math.random()*Math.PI*2,r=shape==='cloud'?.3+Math.random()*1.8:.85;return[Math.sqrt(1-u*u)*Math.cos(a)*r,u*r,Math.sqrt(1-u*u)*Math.sin(a)*r]}
function reset(){targets=Array.from({length:count},(_,i)=>target(i));particles=Array.from({length:count},(_,i)=>particles[i]||[0,0,0]);$('#qualityLabel').textContent=count.toLocaleString()+' PARTICLES';$('#quality').value=String(count)}
function setShape(s){if(shape===s)return;shape=s;targets=Array.from({length:count},(_,i)=>target(i));$('#formName').textContent=names[s];document.querySelectorAll('[data-shape]').forEach(b=>{const yes=b.dataset.shape===s;b.classList.toggle('selected',yes);b.setAttribute('aria-pressed',yes)});if(paused){particles=targets.map(p=>[...p]);draw(0)}}
function resize(){const box=canvas.getBoundingClientRect();width=box.width;height=box.height;const d=Math.min(devicePixelRatio||1,2);canvas.width=width*d;canvas.height=height*d;ctx.setTransform(d,0,0,d,0,0);if(paused)draw(0)}
function draw(dt){ctx.clearRect(0,0,width,height);const rgb=colors[shape],scale=Math.min(width*.23,height*.31),a=((shape==='logo'||shape==='love')?Math.sin(angle)*.13:angle*.35)+pointerX*.35,ca=Math.cos(a),sa=Math.sin(a),tilt=pointerY*.2;ctx.globalCompositeOperation='lighter';for(let i=0;i<count;i++){const p=particles[i],t=targets[i];for(let k=0;k<3;k++)p[k]+=(t[k]-p[k])*(1-Math.exp(-dt*5));const x=p[0]*ca-p[2]*sa,z=p[0]*sa+p[2]*ca,y=p[1]+z*tilt,depth=4/(4+z),sx=width/2+x*scale*depth,sy=height*.47-y*scale*depth,alpha=Math.max(.12,Math.min(.85,.55-z*.14));ctx.fillStyle=`rgba(${rgb[0]},${rgb[1]},${rgb[2]},${alpha})`;ctx.beginPath();ctx.arc(sx,sy,(i%13===0?1.5:.8)*depth,0,Math.PI*2);ctx.fill()}ctx.globalCompositeOperation='source-over'}
function loop(now){const dt=Math.min((now-lastFrame)/1000||.016,.05);lastFrame=now;if(!paused){angle+=dt*.4;draw(dt)}if(tracking&&tracker&&$('#video').readyState>=2&&$('#video').currentTime!==lastVideo){lastVideo=$('#video').currentTime;try{const result=tracker.detectForVideo($('#video'),now);handleHand(result.landmarks,now)}catch(e){stopCamera();$('#status').textContent='Tracking stopped. Try again or use the shape buttons.'}}requestAnimationFrame(loop)}
function distance(a,b){return Math.hypot(a.x-b.x,a.y-b.y,a.z-b.z)}
function handleHand(hands,now){if(!hands.length){candidate='';$('#status').textContent='Show one whole hand to the camera.';return}const h=hands[0];let fingers=0;for(const [tip,pip,mcp]of [[8,6,5],[12,10,9],[16,14,13],[20,18,17]]){const a=h[tip],b=h[pip],c=h[mcp],ux=a.x-b.x,uy=a.y-b.y,uz=a.z-b.z,vx=c.x-b.x,vy=c.y-b.y,vz=c.z-b.z,cos=(ux*vx+uy*vy+uz*vz)/(Math.hypot(ux,uy,uz)*Math.hypot(vx,vy,vz)||1);if(cos<-.65&&distance(a,h[0])>distance(b,h[0])*1.12)fingers++}const next=fingers===0?'logo':fingers===1?'orbit':fingers===2?'heart':fingers===3?'love':fingers===4?'cloud':null;if(!next){candidate='';$('#status').textContent='Use 1, 2, or 3 fingers, an open palm, or a fist.';return}if(next!==candidate){candidate=next;since=now}if(now-since>450){setShape(next);$('#status').textContent=names[next]+' detected · hold a different gesture to change form.'}}
function syncMotion(){$('#motion').textContent=paused?'Resume':'Pause';$('#motion').setAttribute('aria-pressed',paused)}
function stopCamera(){document.body.classList.remove('camera-active');epoch++;tracking=false;starting=false;if(stream)stream.getTracks().forEach(t=>t.stop());stream=null;$('#video').srcObject=null;$('#video').style.display='none';$('#cameraPlaceholder').style.display='block';$('#camera').disabled=false;$('#camera').textContent='Enable hand tracking ↗';$('#previewLabel').textContent='CAMERA OFF';$('#mode').textContent='DEMO MODE';$('#status').textContent='Camera stopped. Explore with the shape buttons.';candidate='';lastVideo=-1}
async function startCamera(){if(tracking||starting){stopCamera();return}if(!window.isSecureContext||!navigator.mediaDevices?.getUserMedia){$('#status').textContent='Camera needs HTTPS and a supported browser. Demo controls still work.';return}const run=++epoch;starting=true;$('#camera').textContent='Cancel camera setup';$('#status').textContent='Requesting camera permission…';try{const incoming=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user',width:{ideal:640},height:{ideal:480}},audio:false});if(run!==epoch){incoming.getTracks().forEach(t=>t.stop());return}stream=incoming;$('#video').srcObject=stream;await $('#video').play();$('#video').style.display='block';$('#cameraPlaceholder').style.display='none';$('#previewLabel').textContent='LOCAL VIDEO';$('#status').textContent='Loading hand model. First start may take a moment…';if(!tracker){const {HandLandmarker,FilesetResolver}=await import('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.21/vision_bundle.mjs');const vision=await FilesetResolver.forVisionTasks('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.21/wasm');const loaded=await HandLandmarker.createFromOptions(vision,{baseOptions:{modelAssetPath:'https://storage.googleapis.com/mediapipe-models/hand_landmarker/hand_landmarker/float16/1/hand_landmarker.task'},runningMode:'VIDEO',numHands:1,minHandDetectionConfidence:.6,minHandPresenceConfidence:.6,minTrackingConfidence:.6});if(run!==epoch){loaded.close();return}tracker=loaded}if(run!==epoch)return;starting=false;tracking=true;document.body.classList.add('camera-active');$('#camera').textContent='Stop camera';$('#mode').textContent='HAND TRACKING';$('#status').textContent='Ready. Hold one hand in view.';stream.getVideoTracks()[0].addEventListener('ended',()=>{if(tracking)stopCamera()})}catch(error){if(run!==epoch)return;stopCamera();$('#status').textContent=error.name==='NotAllowedError'?'Camera permission was not granted. You can use all five demo buttons.':'Camera or model could not start. Check your connection and camera availability, then retry.'}}
$('#camera').addEventListener('click',startCamera);$('#motion').addEventListener('click',()=>{paused=!paused;syncMotion()});$('#quality').addEventListener('change',e=>{count=Number(e.target.value);reset();if(paused){particles=targets.map(p=>[...p]);draw(0)}});document.querySelectorAll('[data-shape]').forEach(b=>b.addEventListener('click',()=>{if(tracking)stopCamera();setShape(b.dataset.shape)}));canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();pointerX=(e.clientX-r.left)/r.width-.5;pointerY=(e.clientY-r.top)/r.height-.5;if(paused)draw(0)});canvas.addEventListener('pointerleave',()=>{pointerX=0;pointerY=0});document.addEventListener('visibilitychange',()=>{if(document.hidden&&(tracking||starting))stopCamera()});window.addEventListener('pagehide',()=>{stopCamera();tracker?.close();tracker=null});reset();particles=targets.map(p=>[...p]);new ResizeObserver(resize).observe(canvas);syncMotion();requestAnimationFrame(loop);

const stage=$('.stage'),fullButton=$('#fullscreen'),hideButton=$('#toggleControls');
function isExpanded(){return document.fullscreenElement===stage||stage.classList.contains('expanded')}
function syncFullscreen(){const active=isExpanded();fullButton.textContent=active?'↙ Exit fullscreen':'⛶ Fullscreen';fullButton.setAttribute('aria-pressed',active);document.body.classList.toggle('stage-expanded',active);if(!active){stage.classList.remove('clean');hideButton.textContent='Hide controls';hideButton.setAttribute('aria-pressed','false')}requestAnimationFrame(resize)}
async function exitExpanded(){if(document.fullscreenElement===stage){try{await document.exitFullscreen()}catch{}}stage.classList.remove('expanded');syncFullscreen();fullButton.focus()}
fullButton.addEventListener('click',async()=>{if(isExpanded()){await exitExpanded();return}try{if(!stage.requestFullscreen)throw new Error('Fullscreen unavailable');await stage.requestFullscreen()}catch{stage.classList.add('expanded')}syncFullscreen()});
hideButton.addEventListener('click',()=>{const hidden=stage.classList.toggle('clean');hideButton.textContent=hidden?'Show controls':'Hide controls';hideButton.setAttribute('aria-pressed',hidden)});
$('#fsStopCamera').addEventListener('click',stopCamera);
document.addEventListener('fullscreenchange',syncFullscreen);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&stage.classList.contains('expanded'))exitExpanded();if(e.key==='Tab'&&stage.classList.contains('expanded')){const focusable=[...stage.querySelectorAll('button')].filter(b=>b.offsetParent!==null),first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
